//! Parts regenerated by host workers the engine cannot wait for (W1b, `oc_engine::hosts`): a
//! request that needs them is deferred, the parts are regenerated by "hosts" (here
//! `oc_host::serve::answer` on this thread, the browser's host worker's job), and the request
//! run again answers exactly as an engine that regenerated them itself.
mod common;

use std::path::Path;

use common::*;
use oc_engine::engine::Engine;
use oc_engine::hosts::{Prepared, DIED, TIMED_OUT};
use oc_engine::request::{request, Answer};
use oc_host::proto;
use oc_kernel_occt::OcctKernel;
use serde_json::{json, Value};

/// A host's reply to job `id`.
type Host<'a> = &'a dyn Fn(u64, &[u8]) -> (u32, Vec<u8>);

fn regenerate(_: u64, job: &[u8]) -> (u32, Vec<u8>) {
    oc_host::serve::answer(&OcctKernel::default(), job, false)
}

/// Runs a request to its end, regenerating deferred parts on `host`: the answer and how many
/// times it was deferred.
fn serve(e: &mut Engine, p: &Prepared, cmd: &str, args: &Value, host: Host<'_>) -> (Answer, usize) {
    let mut rounds = 0;
    loop {
        match request(e, cmd, args.clone()).unwrap() {
            Answer::Deferred => {
                rounds += 1;
                assert!(rounds < 8, "deferred again and again");
                for (i, job) in p.wanted().iter().enumerate() {
                    if job.is_empty() {
                        continue;
                    }
                    let (kind, payload) = host(i as u64, job);
                    p.prepare(i as u64, kind, &payload).unwrap();
                }
            }
            a => {
                p.finish();
                return (a, rounds);
            }
        }
    }
}

fn hinge() -> (Value, String) {
    let path = corpus().join("assemblies/hinge.ocasm");
    let c = oc_doc::container::Container::from_bytes(&std::fs::read(&path).unwrap()).unwrap();
    let doc = oc_doc::load_assembly(c.document().unwrap()).unwrap().doc;
    (serde_json::to_value(doc).unwrap(), path.to_string_lossy().into_owned())
}

/// A build reply without what depends on where and when parts were regenerated.
fn comparable(b: &[u8]) -> (Value, Vec<u8>) {
    let mut h = header(b);
    for k in ["timeMs", "regenMs", "workers", "hosts", "gen"] {
        h.as_object_mut().unwrap().remove(k);
    }
    for (_, p) in h["parts"].as_object_mut().unwrap() {
        p.as_object_mut().unwrap().remove("handle");
    }
    (h, arrays(b).to_vec())
}

/// Each part's display mesh, by part hash.
fn meshes(e: &Engine, b: &[u8]) -> Vec<(String, Vec<u8>)> {
    let h = header(b);
    let store = e.store.meshes.lock().unwrap();
    let mut out: Vec<(String, Vec<u8>)> = h["parts"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(hash, p)| (hash.clone(), store[&(p["handle"].as_u64().unwrap() as u32)].to_bytes()))
        .collect();
    out.sort();
    out
}

fn build_args(doc: &Value, path: &str, lightweight: bool) -> Value {
    json!({ "doc": doc, "path": path, "lightweight": lightweight, "quality": 3, "overrides": {}, "probe": false, "base": null })
}

/// The hinge's three parts regenerated on hosts: one deferral, then the same reply and the
/// same meshes as an engine that regenerated them itself.
#[test]
fn deferred_build_equals_direct() {
    let (doc, path) = hinge();
    let args = build_args(&doc, &path, false);
    let mut direct = engine();
    let want = bytes(&mut direct, "asm_build", args.clone());
    let (mut e, p) = hosted(2);
    let (a, rounds) = serve(&mut e, &p, "asm_build", &args, &regenerate);
    let Answer::Bytes(got) = a else { panic!("not a build reply") };
    assert_eq!(rounds, 1);
    let h = header(&got);
    assert_eq!(h["regenerated"], 3);
    assert_eq!(h["workers"], 2);
    assert_eq!(h["hosts"], json!({ "started": 0, "died": 0, "timedOut": 0, "failedToStart": 0 }));
    assert_eq!(comparable(&got), comparable(&want));
    assert_eq!(meshes(&e, &got), meshes(&direct, &want));
    // Built again: nothing to regenerate, nothing deferred.
    let (_, rounds) = serve(&mut e, &p, "asm_build", &args, &regenerate);
    assert_eq!(rounds, 0);
}

/// A host worker that trapped fails only its part, with the native pool's message; one that
/// did not answer in time likewise; a host that could not read its job leaves the part to
/// the engine.
#[test]
fn a_dead_host_fails_only_its_part() {
    let (doc, path) = hinge();
    let args = build_args(&doc, &path, false);
    let host = |id: u64, _: &[u8]| match id {
        0 => (DIED, vec![]),
        1 => (TIMED_OUT, 600.0f64.to_le_bytes().to_vec()),
        _ => (proto::FAILED, proto::encode_failed(id, "no document")),
    };
    let (mut e, p) = hosted(4);
    let (a, _) = serve(&mut e, &p, "asm_build", &args, &host);
    let Answer::Bytes(got) = a else { panic!("not a build reply") };
    let h = header(&got);
    let errors: Vec<String> = h["parts"].as_object().unwrap().values().map(|p| p["errors"].to_string()).collect();
    assert_eq!(errors.iter().filter(|e| e.contains(oc_host::pool::DIED)).count(), 1, "{errors:?}");
    assert_eq!(errors.iter().filter(|e| e.contains("did not finish within 600 s")).count(), 1, "{errors:?}");
    assert_eq!(errors.iter().filter(|e| e.as_str() == "[]").count(), 1, "{errors:?}");
    assert_eq!(h["hosts"]["died"], 1);
    assert_eq!(h["hosts"]["timedOut"], 1);
    // The failed parts have no mesh; the one the engine regenerated has.
    let handles: Vec<u64> = h["parts"].as_object().unwrap().values().map(|p| p["handle"].as_u64().unwrap()).collect();
    assert_eq!(handles.iter().filter(|h| **h != 0).count(), 1);
}

/// Mass properties of a lightweight assembly whose parts have no B-rep caches: the parts are
/// resolved on hosts (`resolve_many`), with the same answer as an engine resolving them itself.
#[test]
fn deferred_mass_equals_direct() {
    // The hinge with its meshes but without its B-reps.
    let src = corpus().join("assemblies/hinge.ocasm");
    let mut c = oc_doc::container::Container::from_bytes(&std::fs::read(&src).unwrap()).unwrap();
    let breps: Vec<String> = c.names().filter(|n| n.starts_with("cache/brep/")).map(String::from).collect();
    assert!(!breps.is_empty());
    for n in breps {
        c.remove(&n);
    }
    // Next to the hinge: its components are found relative to it.
    let path = corpus().join(format!("assemblies/.hinge-no-breps-{}.ocasm", std::process::id()));
    std::fs::write(&path, c.to_bytes()).unwrap();
    let ps = path.to_string_lossy().into_owned();
    let run = |e: &mut Engine, p: Option<&Prepared>| -> (Value, usize) {
        let open = json(e, "asm_open", json!({ "path": ps }));
        let args = build_args(&open["doc"], &ps, true);
        let b = bytes(e, "asm_build", args);
        assert_eq!(header(&b)["regenerated"], 0, "lightweight from the cached meshes");
        let q = json!({ "quality": 3 });
        match p {
            None => (json(e, "asm_mass", q), 0),
            Some(p) => match serve(e, p, "asm_mass", &q, &regenerate) {
                (Answer::Json(v), n) => (v, n),
                _ => panic!("not JSON"),
            },
        }
    };
    let (want, _) = run(&mut engine(), None);
    let (mut e, p) = hosted(3);
    let (got, rounds) = run(&mut e, Some(&p));
    let _ = std::fs::remove_file(Path::new(&path));
    assert_eq!(rounds, 1);
    assert_eq!(want["regenerated"], 3);
    assert_eq!(got, want);
}

/// With deferring off (no host workers left), parts are regenerated by the engine.
#[test]
fn without_deferring_the_engine_regenerates() {
    let (doc, path) = hinge();
    let args = build_args(&doc, &path, false);
    let (mut e, p) = hosted(2);
    p.set_defer(false);
    let got = bytes(&mut e, "asm_build", args.clone());
    let want = bytes(&mut engine(), "asm_build", args);
    assert_eq!(comparable(&got).0["parts"], comparable(&want).0["parts"]);
}
